{
  "findings": [
    {
      "claim": "An empty project causes ratio(0, 0) to panic on division by zero.",
      "criterion": "Add `ratio(done, total)`, the share of done items as a whole percentage. A project may have no items yet.",
      "evidence": "src/lib.rs:2 divides by total without handling zero.",
      "id": "F1",
      "settle": "Define and implement the percentage for an empty project, with a regression test for ratio(0, 0).",
      "severity": "blocker"
    },
    {
      "claim": "Multiplication overflows for valid large item counts, causing a panic with overflow checks or an incorrect percentage without them.",
      "criterion": "Add `ratio(done, total)`, the share of done items as a whole percentage.",
      "evidence": "src/lib.rs:2 computes done * 100 as u32. For ratio(50_000_000, 50_000_000), the intermediate 5_000_000_000 exceeds u32::MAX; wrapping produces 14 instead of 100.",
      "id": "F2",
      "settle": "Use a sufficiently wide intermediate type and cover large valid counts with a regression test.",
      "severity": "blocker"
    }
  ],
  "format": 9,
  "status": "done",
  "summary": "Two defects: empty projects trigger division by zero, and large item counts overflow the percentage calculation. Review used static inspection only."
}
